def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    letras = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = []
    for i, val in enumerate(valores):
        while n >= val:
            resultado.append(letras[i])
            n -= val

    return "".join(reversed(resultado))

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10,
        'L': 50, 'C': 100,
        'D': 500, 'M': 1000
    }
    result = 0
    prev_val = 0
    for char in reversed(s):
        if char in roman_map:
            val = roman_map[char]
            if prev_val > 0 and val < prev_val:
                result -= val
            else:
                result += val
            prev_val = val
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 0
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == max_element:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i-1]
            current_racha = 1

    if current_racha > max_racha:
