def a_camel(s):
    if not s:
        return ""
    words = s.split()
    if not words:
        return ""
    result = words[0]
    for word in words[1:]:
        result += word[0].upper() + word[1:]
    return result

def a_snake(s):
    if not s:
        return ""
    result = []
    prev_is_upper = False
    for char in s:
        if char.isupper():
            if prev_is_upper:
                result.append("-")
            result.append(char.lower())
            prev_is_upper = True
        else:
            result.append(char.lower())
            prev_is_upper = False
    return "".join(result)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

